import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    return 0.5 * x1**2 + 0.3 * x2**2 + 0.2 * x1*x2 + 0.1 * (x1**3 - x2**3)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1 = x[0]
    x2 = x[1]
    f = (x1**2 + 0.5*x2**2 + 0.5*x1*x2 + x1**3*0.1) + np.sin(x1 * 2) * 0.2 + np.sin(x2 * 3) * 0.1 + np.sin((x1 + x2) * 1.5) * 0.15
    return float(f)

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x

    quadratic_term = x1**2 + 2 * x2**2
    if (x1<1) :
        quadratic_term *= np.exp(-x1)*.5;
    quadratic_term *= 0.3

    interaction_term = np.sin(x1) * np.cos(x2) * 0.02

    window = 0.5 * (1 + np.cos(np.pi * (x1 + x2) / 10))

    return (quadratic_term + interaction_term) * window

import numpy as np

def problem(x: np.ndarray) -> float:
    x1, x2 = x
    return ((x1**2 + x2**2) * np.exp(0.1 * x1) + 0.1 * x1 * x2) * (0.5 + 0.5 * np.cos(0.2 * np.pi * (x1 + x2)))
